'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { HOTELS, ACTIVITIES, RESTAURANTS, regions } from '@/data/db';

type Region = typeof regions[0];
type Hotel = typeof HOTELS[0];
type Activity = typeof ACTIVITIES[0];
type Restaurant = typeof RESTAURANTS[0];

interface TripData {
  region: Region | null;
  hotel: Hotel | null;
  activities: Activity[];
  restaurants: Restaurant[];
}

interface TripContextType {
  tripData: TripData;
  setRegion: (regionId: string) => void;
  setHotel: (hotelId: string) => void;
  addActivity: (activityId: string) => void;
  removeActivity: (activityId: string) => void;
  addRestaurant: (restaurantId: string) => void;
  removeRestaurant: (restaurantId: string) => void;
  totalPrice: number;
  resetTrip: () => void;
}

const TripContext = createContext<TripContextType | undefined>(undefined);

export function TripProvider({ children }: { children: React.ReactNode }) {
  const [tripData, setTripData] = useState<TripData>({
    region: null,
    hotel: null,
    activities: [],
    restaurants: []
  });

  const setRegion = (regionId: string) => {
    const region = regions.find(r => r.id === regionId) || null;
    // Reset selections if region changes
    if (region?.id !== tripData.region?.id) {
        setTripData({
            region,
            hotel: null,
            activities: [],
            restaurants: []
        });
    } else {
        setTripData(prev => ({ ...prev, region }));
    }
  };

  const setHotel = (hotelId: string) => {
    const hotel = HOTELS.find(h => h.id === hotelId) || null;
    setTripData(prev => ({ ...prev, hotel }));
  };

  const addActivity = (activityId: string) => {
    const activity = ACTIVITIES.find(a => a.id === activityId);
    if (activity && !tripData.activities.find(a => a.id === activityId)) {
      setTripData(prev => ({ ...prev, activities: [...prev.activities, activity] }));
    }
  };

  const removeActivity = (activityId: string) => {
    setTripData(prev => ({
      ...prev,
      activities: prev.activities.filter(a => a.id !== activityId)
    }));
  };

  const addRestaurant = (restaurantId: string) => {
    const restaurant = RESTAURANTS.find(r => r.id === restaurantId);
    if (restaurant && !tripData.restaurants.find(r => r.id === restaurantId)) {
      setTripData(prev => ({ ...prev, restaurants: [...prev.restaurants, restaurant] }));
    }
  };

  const removeRestaurant = (restaurantId: string) => {
    setTripData(prev => ({
      ...prev,
      restaurants: prev.restaurants.filter(r => r.id !== restaurantId)
    }));
  };

  const resetTrip = () => {
    setTripData({
      region: null,
      hotel: null,
      activities: [],
      restaurants: []
    });
  };

  const totalPrice = React.useMemo(() => {
    let total = 0;
    if (tripData.hotel) total += tripData.hotel.price;
    tripData.activities.forEach(a => total += a.price);
    tripData.restaurants.forEach(r => total += r.price);
    return total;
  }, [tripData]);

  return (
    <TripContext.Provider value={{
      tripData,
      setRegion,
      setHotel,
      addActivity,
      removeActivity,
      addRestaurant,
      removeRestaurant,
      totalPrice,
      resetTrip
    }}>
      {children}
    </TripContext.Provider>
  );
}

export function useTrip() {
  const context = useContext(TripContext);
  if (context === undefined) {
    throw new Error('useTrip must be used within a TripProvider');
  }
  return context;
}
